 HWND slider(int tab,int id,int y,int lo,int hi,int value){HWND h=control(tab,id,TRACKBAR_CLASSW,L"",12,y,PANEL-24,32,TBS_AUTOTICKS);SendMessageW(h,TBM_SETRANGEMIN,FALSE,lo);SendMessageW(h,TBM_SETRANGEMAX,TRUE,hi);SendMessageW(h,TBM_SETPOS,TRUE,value);return h;}
