 void layout(){if(!window_||!preview_)return;RECT r;GetClientRect(window_,&r);int w=std::max<LONG>(1,r.right),h=std::max<LONG>(1,r.bottom);MoveWindow(preview_,PANEL,0,std::max(1,w-PANEL),std::max(1,h),TRUE);if(status_)MoveWindow(status_,12,std::max(1,h-34),PANEL-24,24,TRUE);}
 lab::BumpPair manualBump(){if(useImported_&&importedBump_.valid()&&importedBumpX_.valid())return {importedBump_,importedBumpX_};lab::Settings neutral=settings_;neutral.normalStrength=1.f;neutral.invertY=false;return lab::GenerateBump(sources_,neutral);}
 void updateManualPreview(bool replaceDiffuse=false){if(!ready_)return;lab::BumpPair b=manualBump();if(!b.bump.valid()){status(L"Bump: ошибка");return;}if(replaceDiffuse)render_.SetImages(sources_.diffuse,b.bump,b.bumpX);else render_.SetBumpImages(b.bump,b.bumpX,true);render_.SetNormalSettings(settings_.normalStrength,settings_.invertY);autoModelMaterials_=false;InvalidateRect(preview_,nullptr,FALSE);}
 void loadSlot(int id){auto filename=pick(window_,L"Image (*.dds;*.png;*.jpg;*.bmp;*.tif)\0*.dds;*.png;*.jpg;*.jpeg;*.bmp;*.tif;*.tiff\0All files\0*.*\0",L"dds");if(filename.empty())return;std::wstring error;auto im=loadImage(filename,error);if(!im.valid()){MessageBoxW(window_,error.c_str(),L"Image",MB_ICONERROR);return;}if(id==LOAD_DIFF){sources_.diffuse=std::move(im);manualTexturePath_=filename;}else if(id==LOAD_NORMAL)sources_.normal=std::move(im);else if(id==LOAD_GLOSS)sources_.gloss=std::move(im);else if(id==LOAD_HEIGHT)sources_.height=std::move(im);else if(id==LOAD_BUMP)importedBump_=std::move(im);else if(id==LOAD_BUMPX)importedBumpX_=std::move(im);if(id==LOAD_BUMP||id==LOAD_BUMPX){useImported_=importedBump_.valid()&&importedBumpX_.valid();if(!useImported_){status(L"Нужна пара bump/bump#");return;}}else useImported_=false;updateManualPreview(id==LOAD_DIFF);status(std::filesystem::path(filename).filename().wstring());}
 void openOGF(){auto filename=pick(window_,L"S.T.A.L.K.E.R. OGF (*.ogf)\0*.ogf\0All files\0*.*\0",L"ogf");if(filename.empty())return;auto bytes=readFile(filename);std::string reason;lab::Mesh m;if(!lab::LoadOGFMesh(bytes,m,reason)){std::wstring why(reason.begin(),reason.end());MessageBoxW(window_,why.c_str(),L"OGF",MB_ICONWARNING);status(why);return;}std::wstring err;if(!render_.SetMesh(m,err)){MessageBoxW(window_,err.c_str(),L"OGF",MB_ICONERROR);return;}currentMesh_=m;modelPath_=filename;manualTexturePath_.clear();render_.Reset();SendMessageW(controls_[SLIDER_LIGHT_AZ],TBM_SETPOS,TRUE,52);SendMessageW(controls_[SLIDER_LIGHT_EL],TBM_SETPOS,TRUE,37);render_.ClearSelection();sources_=lab::Sources{};sources_.diffuse=lab::DefaultChecker();importedBump_={};importedBumpX_={};useImported_=false;autoModelMaterials_=true;render_.SetNormalSettings(settings_.normalStrength,settings_.invertY);
  std::filesystem::path texturesRoot;bool hasRoot=findTexturesRoot(std::filesystem::path(filename),texturesRoot);size_t texOk=0,bumpOk=0;lab::Image firstDiffuse;lab::BumpPair firstBump;
  for(size_t i=0;i<m.parts.size();++i){lab::PartImages images;images.diffuse=lab::DefaultChecker(128);const auto& part=m.parts[i];if(!part.texture.empty()&&hasRoot){std::filesystem::path d,b,bx;std::wstring note;if(resolveOGFMaterialPaths(texturesRoot,part.texture,d,b,bx,note)){if(std::filesystem::exists(d)){std::wstring e;auto diffuse=loadImage(d.wstring(),e);if(diffuse.valid()){images.diffuse=diffuse;++texOk;if(!firstDiffuse.valid())firstDiffuse=diffuse;}}if(std::filesystem::exists(b)&&std::filesystem::exists(bx)){std::wstring e1,e2;auto bi=loadImage(b.wstring(),e1),bxi=loadImage(bx.wstring(),e2);if(bi.valid()&&bxi.valid()){images.bump=bi;images.bumpX=bxi;images.hasBump=true;++bumpOk;if(!firstBump.bump.valid())firstBump={bi,bxi};}}}}render_.SetPartImages(i,images);}
  if(m.parts.size()==1&&firstDiffuse.valid()){sources_.diffuse=firstDiffuse;if(firstBump.bump.valid()){importedBump_=firstBump.bump;importedBumpX_=firstBump.bumpX;useImported_=true;}}
  bool skeleton=render_.HasSkeleton();SendMessageW(controls_[SKELETON_ENABLED],BM_SETCHECK,skeleton?BST_CHECKED:BST_UNCHECKED,0);EnableWindow(controls_[SKELETON_ENABLED],skeleton);render_.SkeletonEnabled(skeleton);status(L"OGF: "+std::to_wstring(m.parts.size())+L" | Tex: "+std::to_wstring(texOk)+L" | Bump: "+std::to_wstring(bumpOk)+L" | Bones: "+std::to_wstring(m.bones.size()));InvalidateRect(preview_,nullptr,FALSE);}
 void chooseColor(int which){static COLORREF saved[16]={};CHOOSECOLORW cc={};cc.lStructSize=sizeof(cc);cc.hwndOwner=window_;cc.rgbResult=render_.GetColor(which);cc.lpCustColors=saved;cc.Flags=CC_RGBINIT|CC_FULLOPEN;if(ChooseColorW(&cc)){render_.SetColor(which,cc.rgbResult);InvalidateRect(preview_,nullptr,FALSE);}}
 std::wstring selectedTextureName()const{if(!manualTexturePath_.empty())return cleanName(manualTexturePath_.stem().wstring());int selected=render_.SelectedPart();if(selected>=0&&size_t(selected)<currentMesh_.parts.size()){auto n=textureStem(currentMesh_.parts[size_t(selected)].texture);if(!n.empty())return n;}for(const auto& p:currentMesh_.parts){auto n=textureStem(p.texture);if(!n.empty())return n;}return {};}
