 void exportDDS(){bool useTexture=controls_[USE_TEX_NAME]&&SendMessageW(controls_[USE_TEX_NAME],BM_GETCHECK,0,0)==BST_CHECKED;std::wstring stem;if(useTexture)stem=selectedTextureName();if(stem.empty())stem=customName();if(stem.empty()&&!modelPath_.empty())stem=cleanName(modelPath_.stem().wstring());if(stem.empty())stem=selectedTextureName();if(stem.empty())stem=L"material";std::wstring modelFolder=!modelPath_.empty()?cleanName(modelPath_.stem().wstring()):stem;if(modelFolder.empty())modelFolder=L"material";std::filesystem::path folder=exeDir()/L"export"/modelFolder;std::error_code ec;std::filesystem::create_directories(folder,ec);if(ec){std::wstring ws=L"Не удалось создать "+folder.wstring();MessageBoxW(window_,ws.c_str(),L"Export",MB_ICONERROR);status(ws);return;}std::filesystem::path base=folder/stem;std::string err;if(!lab::ExportBumpPair(sources_,settings_,base.wstring(),err)){std::wstring ws(err.begin(),err.end());MessageBoxW(window_,ws.c_str(),L"Export",MB_ICONERROR);status(ws);return;}status((folder/(stem+L"_bump.dds")).wstring());}
